/* demo/research.js: "Research behind the numbers" (UI revamp lane L9, D69).
 *
 * Builds the whole page from window.RESEARCH_DATA (data/research_bundle.js, generated by demo/export_research.py
 * from docs/research_claims.yaml). No claim text, count or figure is typed here: every one is read from the bundle.
 * research.html#<claim id> opens and expands that claim's row (on load and on hashchange).
 */
(function () {
  "use strict";

  var D = window.RESEARCH_DATA;
  var BASES = ["published", "simulation", "assumption"];
  // the finer split of simulated waiting days (waiting_split.*.by_basis_share)
  var WAIT_BASES = ["published", "calibrated", "assumption"];
  var ACCESS = {
    full_text: "Full text",
    abstract: "Abstract only",
    secondary: "Secondary account"
  };
  var BASIS_HINT = {
    published: "A source in our registry, with how we read it",
    simulation: "Computed on synthetic patients; rests on our inputs",
    assumption: "Our own choice, with the reason written down"
  };

  function $(id) { return document.getElementById(id); }

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return {"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"}[c];
    });
  }

  function pct(share) { return Math.round(share * 100); }

  function fmtDays(x) {
    var n = Number(x);
    return isFinite(n) ? n.toFixed(1) : esc(x);
  }

  function fmtInt(n) {
    return Number(n).toLocaleString("en-GB");
  }

  // Inline text from the register: `code` spans become <code>; claim ids become links to their rows.
  var claimIds = {};
  function rich(text) {
    var out = esc(text).replace(/`([^`]+)`/g, "<code>$1</code>");
    return out.replace(/\b[a-z0-9]+(?:-[a-z0-9]+)+\b/g, function (m) {
      return claimIds[m] ? '<a href="#' + m + '">' + m + "</a>" : m;
    });
  }

  function link(url, text) {
    return '<a href="' + esc(url) + '" target="_blank" rel="noopener noreferrer">' + esc(text || url) + "</a>";
  }

  function chip(basis, extra) {
    var label = (D.basis_labels && D.basis_labels[basis]) || basis;
    return '<span class="chip rs-chip rs-chip--' + esc(basis) + (extra ? " " + extra : "") + '">' + esc(label) + "</span>";
  }

  // The register's theme list is a YAML flow mapping, so a title containing a comma arrives split into extra keys
  // with null values ({"title": "What the Norwegian study found", "and how our model compares": null}).
  // Join them back so the heading reads as written in docs/research_claims.yaml.
  function themeTitle(t) {
    var parts = [t.title];
    Object.keys(t).forEach(function (k) {
      if (k !== "id" && k !== "title" && t[k] === null) parts.push(k);
    });
    return parts.join(", ");
  }

  /* ---------- top: claims by basis ---------- */
  function renderBasis() {
    var counts = D.counts || {};
    var total = BASES.reduce(function (a, b) { return a + (counts[b] || 0); }, 0);
    $("rs-basis-bar").setAttribute("aria-label", "Claims by basis: " + BASES.map(function (b) {
      return D.basis_labels[b] + " " + counts[b];
    }).join(", "));
    $("rs-basis-bar").innerHTML = BASES.map(function (b) {
      var w = total ? (counts[b] || 0) / total * 100 : 0;
      return '<span class="rs-seg rs-seg--' + b + '" style="flex-basis:' + w + '%"></span>';
    }).join("");
    $("rs-basis-cards").innerHTML = BASES.map(function (b) {
      return '<a class="rs-basis-card rs-basis-card--' + b + '" href="#rs-claims" data-basis="' + b + '">' +
        '<span class="num num--big">' + esc(counts[b]) + "</span>" +
        chip(b) +
        '<span class="rs-basis-hint">' + esc(BASIS_HINT[b]) + "</span></a>";
    }).join("");
    Array.prototype.forEach.call(document.querySelectorAll(".rs-basis-card"), function (a) {
      a.addEventListener("click", function () { setFilter(a.getAttribute("data-basis")); });
    });
  }

  /* ---------- top: the worked waiting example ---------- */
  function splitRow(name, part, sentence, claimId) {
    var share = part.by_basis_share || {};
    var segs = WAIT_BASES.map(function (b) {
      var p = pct(share[b] || 0);
      var lbl = p >= 8 ? p + "%" : "";
      return '<span class="rs-wseg rs-wseg--' + b + '" style="flex-basis:' + ((share[b] || 0) * 100) + '%" title="' +
        esc(D.waiting_split.basis_labels[b] + ": " + p + "%") + '">' + lbl + "</span>";
    }).join("");
    return '<div class="rs-split-row">' +
      '<div class="rs-split-name"><span class="label">' + esc(name) + "</span>" +
      '<span class="rs-split-sentence">' + sentence + ' <a href="#' + claimId + '">Claim</a></span></div>' +
      '<div class="rs-wbar" role="img" aria-label="' + esc(name + ": " + WAIT_BASES.map(function (b) {
        return D.waiting_split.basis_labels[b] + " " + pct(share[b] || 0) + "%";
      }).join(", ")) + '">' + segs + "</div></div>";
  }

  function renderWorked() {
    var ws = D.waiting_split, v = ws.values;
    var fi = splitRow("Finnish pathway · synthetic county", ws.finland,
      '<b class="num">' + esc(v.fi_matched_pct) + "%</b> of waiting days set from or tuned to a published figure, " +
      '<b class="num">' + esc(v.fi_assumed_pct) + "%</b> resting on our assumptions.",
      "in-fi-waits-half-published");
    var no = splitRow("Norwegian hospital · Stokstad et al.", ws.norway,
      '<b class="num">' + esc(v.no_matched_pct) + "%</b> set from or tuned to the study's published waits, " +
      '<b class="num">' + esc(v.no_assumed_pct) + "%</b> resting on our assumptions.",
      "in-no-waits-published");
    $("rs-split").innerHTML = fi + no;
    $("rs-split-legend").innerHTML = WAIT_BASES.map(function (b) {
      return '<span class="rs-key"><span class="rs-swatch rs-wseg--' + b + '"></span>' +
        esc(ws.basis_labels[b]) + "</span>";
    }).join("");
  }

  /* ---------- framing sentence, verbatim ---------- */
  function renderFraming() {
    $("rs-framing").innerHTML = '<span class="label">What the research shows and what our tool adds</span><p>' +
      esc(D.framing) + "</p>";
  }

  /* ---------- what we could not support ---------- */
  function renderUnsupported() {
    $("rs-unsupported-list").innerHTML = (D.unsupported || []).map(function (u) {
      var links = (u.links || []).map(function (l) { return link(l, "Source"); }).join(" · ");
      return '<article class="rs-unsup" id="' + esc(u.id) + '">' +
        '<p class="rs-unsup-claim">' + esc(u.claim) + "</p>" +
        '<p class="rs-unsup-status"><span class="label">Status</span> ' + rich(u.status) + "</p>" +
        '<p class="rs-unsup-detail">' + rich(u.detail) + (links ? " " + links : "") + "</p></article>";
    }).join("");
  }

  /* ---------- claims ---------- */
  function field(label, html) {
    if (html == null || html === "") return "";
    return "<dt>" + esc(label) + "</dt><dd>" + html + "</dd>";
  }

  function claimBody(c) {
    var dl = "";
    if (c.basis === "published") {
      dl += field("Source", "<code>" + esc(c.source) + "</code> · " + esc(c.citation) +
        (c.year != null && String(c.citation).indexOf(String(c.year)) < 0 ? " (" + esc(c.year) + ")" : ""));
      dl += field("Figure", esc(c.figure));
      dl += field("Kind of source", esc(c.kind));
      dl += field("How we read it", c.access ? '<span class="rs-access rs-access--' + esc(c.access) + '">' +
        esc(ACCESS[c.access] || c.access) + "</span>" : "");
      dl += field("Link", c.url ? link(c.url) : "");
    } else if (c.basis === "simulation") {
      dl += field("Run", rich(c.run));
      dl += field("Inputs", rich(c.inputs));
    } else if (c.basis === "assumption") {
      dl += field("Where", rich(c.where));
      dl += field("Reason", rich(c.reason));
    }
    dl += field("Strength", rich(c.strength));
    dl += field("Shown on", (c.shown_on || []).length ? "<ul>" + c.shown_on.map(function (s) {
      return "<li>" + rich(s) + "</li>";
    }).join("") + "</ul>" : "");
    dl += field("Link to this claim", '<a href="#' + esc(c.id) + '"><code>research.html#' + esc(c.id) + "</code></a>");
    return '<dl class="rs-fields">' + dl + "</dl>";
  }

  function renderClaims() {
    var byTheme = {};
    D.claims.forEach(function (c) { (byTheme[c.theme] = byTheme[c.theme] || []).push(c); });
    var themes = (D.themes || []).slice();
    // claims whose theme is missing from the list still appear, at the end
    Object.keys(byTheme).forEach(function (t) {
      if (!themes.some(function (x) { return x.id === t; })) themes.push({id: t, title: t});
    });
    $("rs-claim-list").innerHTML = themes.map(function (t) {
      var rows = byTheme[t.id] || [];
      if (!rows.length) return "";
      return '<section class="rs-theme" data-theme-id="' + esc(t.id) + '">' +
        '<h4 class="rs-theme-title">' + esc(themeTitle(t)) + "</h4>" +
        rows.map(function (c) {
          return '<details class="rs-claim rs-claim--' + esc(c.basis) + '" id="' + esc(c.id) + '" data-basis="' +
            esc(c.basis) + '">' +
            '<summary><span class="rs-claim-chip">' + chip(c.basis) + "</span>" +
            '<span class="rs-claim-text">' + esc(c.claim) + "</span>" +
            '<span class="rs-claim-id"><code>' + esc(c.id) + "</code></span>" +
            '<span class="rs-claim-toggle" aria-hidden="true"></span></summary>' +
            claimBody(c) + "</details>";
        }).join("") + "</section>";
    }).join("");
  }

  /* ---------- filter by basis ---------- */
  var filter = "all";
  function renderFilter() {
    var opts = [["all", "All"]].concat(BASES.map(function (b) { return [b, D.basis_labels[b]]; }));
    $("rs-filter").innerHTML = opts.map(function (o) {
      var n = o[0] === "all" ? D.claims.length : (D.counts[o[0]] || 0);
      return '<button type="button" class="chip rs-filter-btn" data-filter="' + o[0] + '" aria-pressed="' +
        (o[0] === filter) + '">' + esc(o[1]) + " · " + n + "</button>";
    }).join(" ");
    Array.prototype.forEach.call(document.querySelectorAll(".rs-filter-btn"), function (b) {
      b.addEventListener("click", function () { setFilter(b.getAttribute("data-filter")); });
    });
  }

  function setFilter(f) {
    filter = f || "all";
    Array.prototype.forEach.call(document.querySelectorAll(".rs-filter-btn"), function (b) {
      b.setAttribute("aria-pressed", String(b.getAttribute("data-filter") === filter));
    });
    Array.prototype.forEach.call(document.querySelectorAll(".rs-claim"), function (el) {
      el.hidden = filter !== "all" && el.getAttribute("data-basis") !== filter;
    });
    Array.prototype.forEach.call(document.querySelectorAll(".rs-theme"), function (sec) {
      sec.hidden = !sec.querySelector(".rs-claim:not([hidden])");
    });
  }

  function setAllOpen(open) {
    Array.prototype.forEach.call(document.querySelectorAll(".rs-claim:not([hidden])"), function (el) {
      el.open = open;
    });
  }

  /* ---------- waiting split tables ---------- */
  function waitingTable(title, part) {
    var labels = D.waiting_split.basis_labels;
    var rows = (part.owners || []).map(function (o) {
      return "<tr><td><code>" + esc(o.owner) + "</code>" +
        ((o.tests || []).length ? '<div class="rs-tests">' + o.tests.map(esc).join(", ") + "</div>" : "") + "</td>" +
        '<td><span class="rs-wbasis rs-wbasis--' + esc(o.basis) + '">' + esc(labels[o.basis] || o.basis) + "</span></td>" +
        "<td>" + (o.source ? "<code>" + esc(o.source) + "</code>" : "") + "</td>" +
        '<td class="rs-n">' + fmtDays(o.days) + "</td>" +
        '<td class="rs-n">' + pct(o.share_of_waiting) + "%</td>" +
        "<td>" + rich(o.why) + "</td></tr>";
    }).join("");
    var cap = "<code>" + esc(part.scenario) + "</code>, flowchart <code>" + esc(part.flowchart) + "</code>, seed " +
      esc(part.seed) + ", " + fmtInt(part.patients) + " synthetic patients, " + fmtInt(part.treated_cancers) +
      " treated cancers. Waiting " + fmtDays(part.waiting_days) + " days and service " + fmtDays(part.service_days) +
      " days on the critical path; waiting is " + pct(part.waiting_share_of_time) + "% of the time.";
    return '<div class="rs-table-wrap"><h4 class="rs-theme-title">' + esc(title) + "</h4>" +
      '<p class="caption">' + cap + "</p>" +
      '<table class="rs-table rs-wtable"><thead><tr><th>Where the wait is</th><th>Basis</th><th>Source</th>' +
      '<th class="rs-n">Days</th><th class="rs-n">Share</th><th>Why</th></tr></thead><tbody>' + rows +
      "</tbody></table></div>";
  }

  function renderWaiting() {
    var ws = D.waiting_split;
    $("rs-waiting-tables").innerHTML =
      waitingTable("Finnish pathway (synthetic county), today's pathway", ws.finland) +
      waitingTable("Norwegian hospital (Stokstad et al.), observed pathway", ws.norway);
  }

  /* ---------- sources ---------- */
  function renderSources() {
    var src = (D.sources || []).slice();
    src.sort(function (a, b) { return (b.used_in_register ? 1 : 0) - (a.used_in_register ? 1 : 0); });
    var rows = src.map(function (s) {
      return '<tr class="' + (s.used_in_register ? "rs-used" : "") + '" id="src-' + esc(s.id) + '">' +
        "<td><code>" + esc(s.id) + "</code>" +
        (s.used_in_register ? '<div><span class="chip rs-used-chip">Cited by a claim</span></div>' : "") + "</td>" +
        "<td>" + esc(s.citation) +
        ((s.supports || []).length ? '<div class="rs-supports">Supports: ' + s.supports.map(esc).join("; ") + "</div>" : "") +
        "</td>" +
        '<td class="rs-n">' + esc(s.year == null ? "" : s.year) + "</td>" +
        "<td>" + (s.access ? '<span class="rs-access rs-access--' + esc(s.access) + '">' +
          esc(ACCESS[s.access] || s.access) + "</span>" : "") + "</td>" +
        '<td class="rs-nowrap">' + (s.url ? link(s.url, "Open") : "") + "</td></tr>";
    }).join("");
    $("rs-source-table").innerHTML = '<table class="rs-table rs-sources"><thead><tr><th>Id</th><th>Citation</th>' +
      '<th class="rs-n">Year</th><th>How we read it</th><th>Link</th></tr></thead><tbody>' + rows +
      "</tbody></table>";
  }

  /* ---------- deep links: research.html#<claim id> ---------- */
  function openHash() {
    var id;
    try { id = decodeURIComponent((location.hash || "").slice(1)); } catch (e) { id = ""; }
    if (!id) return;
    var el = document.getElementById(id);
    if (!el) return;
    if (el.classList.contains("rs-claim")) {
      if (el.hidden) setFilter("all");
      el.open = true;
    }
    Array.prototype.forEach.call(document.querySelectorAll(".rs-target"), function (x) {
      x.classList.remove("rs-target");
    });
    if (el.classList.contains("rs-claim") || el.classList.contains("rs-unsup")) el.classList.add("rs-target");
    el.scrollIntoView({block: "start"});
  }

  function renderFooter() {
    var text = "Synthetic patients only · not clinically reviewed · claims read from the research register" +
      (D.generated_at ? ", generated " + String(D.generated_at).replace("T", " ").replace(/:\d\d(\.\d+)?\+00:00$/, " UTC") : "");
    if (window.Site && Site.footer) Site.footer(text);
    else $("rs-footer").textContent = text;
  }

  function init() {
    if (!D || !D.claims) {
      $("rs-claim-list").textContent = "The research bundle (data/research_bundle.js) did not load.";
      return;
    }
    D.claims.forEach(function (c) { claimIds[c.id] = true; });
    (D.unsupported || []).forEach(function (u) { claimIds[u.id] = true; });
    renderBasis();
    renderWorked();
    renderFraming();
    renderUnsupported();
    renderFilter();
    renderClaims();
    renderWaiting();
    renderSources();
    renderFooter();
    $("rs-open-all").addEventListener("click", function () { setAllOpen(true); });
    $("rs-close-all").addEventListener("click", function () { setAllOpen(false); });
    window.addEventListener("hashchange", openHash);
    openHash();
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
